class Solution { public:long long maximumSubarraySum(vector<int>& nums,int k){unordered_map<int,long long> minimumPrefix;long long prefix=0,answer=LLONG_MIN;for(int value:nums){long long endPrefix=prefix+value;auto first=minimumPrefix.find(value-k),second=minimumPrefix.find(value+k);if(first!=minimumPrefix.end())answer=max(answer,endPrefix-first->second);if(second!=minimumPrefix.end())answer=max(answer,endPrefix-second->second);auto current=minimumPrefix.find(value);if(current==minimumPrefix.end())minimumPrefix[value]=prefix;else current->second=min(current->second,prefix);prefix=endPrefix;}return answer==LLONG_MIN?0:answer;} };
